//! 📨️ One selected Event stays owned until its guest finishes and its physical source closes.
use semio_framework_actor::{OriginalActorInput,RetainedTurnInput,RetainedTurnReceipt,ActorGuestPhase};
use semio_framework::kernel::{Event,TurnResult,Effect};
use semio_framework_value::retirement::controlled::ControlledRetirement;
use semio_framework_ui_runtime::{UiNativeMeshMessage,UI_NATIVE_MESH_MESSAGE_BYTES};
use semio_framework_value::{ErasedSnapshotRetirement,ValueError,ValueRefusalKind,RetainedCloneGrant,RetainedCloneProgress};
use std::mem::ManuallyDrop;
use semio_framework_plugin_guest_contract::TurnFault;

struct OriginalShardMeshSending{input:RetainedTurnInput,policy:RetainedCloneGrant,index:usize,sequence:u64,source:(usize,usize,usize),bytes:[u8;UI_NATIVE_MESH_MESSAGE_BYTES],offset:usize,spent:RetainedCloneProgress,work:u64,fuel:u64,sent:bool,accepted:bool,close:ManuallyDrop<Option<ControlledRetirement<Effect>>>}
pub(super) struct OriginalShardEvent{mesh:Option<OriginalShardMeshSending>,mesh_sequence:u64,pub(super) input:OriginalActorInput<Event>,pending:ManuallyDrop<Option<TurnResult>>,retirement:ManuallyDrop<Option<Box<dyn ErasedSnapshotRetirement>>>,frame_bytes:usize,trap:ManuallyDrop<Option<TurnFault>>,failed:Option<semio_framework_plugin_guest_contract::original_actor_context::OriginalActorFixedCall>,receiving_refusal:ManuallyDrop<Option<ValueError>>,source_refusal:ManuallyDrop<Option<ValueError>>}
impl std::fmt::Debug for OriginalShardEvent{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{f.debug_struct("OriginalShardEvent").field("input",&self.input).field("pending",&self.pending.is_some()).field("retirement",&self.retirement.is_some()).finish()}}
impl OriginalShardEvent{
 pub(super) fn new(event:Event,issued:RetainedTurnInput)->Result<Self,(ValueError,Event)>{OriginalActorInput::new(event,issued).map(|input|Self{mesh:None,mesh_sequence:1,input,pending:ManuallyDrop::new(None),retirement:ManuallyDrop::new(None),frame_bytes:0,trap:ManuallyDrop::new(None),failed:None,receiving_refusal:ManuallyDrop::new(None),source_refusal:ManuallyDrop::new(None)})}
 pub(super) fn receive_next_issued(&mut self,input:RetainedTurnInput)->Result<(),ValueError>{self.input.receive_next_issued(input)}
 pub(super) fn is_retiring(&self)->bool{self.pending.is_some()}
 pub(super) fn retain_dispatched_result(&mut self,result:TurnResult)->Result<(),ValueError>{assert!(self.pending.is_none(),"original Event has one returned result");*self.pending=Some(result);let receipt=self.pending.as_ref().unwrap().retained_receipt;self.input.receive_guest(receipt,ActorGuestPhase::Dispatched)}
 pub(super) fn checkout_result_receiving(&mut self,policy:RetainedCloneGrant)->Result<Option<RetainedTurnInput>,ValueError>{if self.pending.is_none(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original receiving has no held guest result"))}self.input.checkout_guest(policy)}
 pub(super) fn pending_result_for_receiving(&mut self,input:RetainedTurnInput)->Result<&mut TurnResult,ValueError>{self.input.original_mut_for_guest(input)?;self.pending.as_mut().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"original receiving result has no held owner"))}
 pub(super) fn receive_result_progress(&mut self,input:RetainedTurnInput,progress:RetainedCloneProgress,work_units_spent:u64)->Result<(),ValueError>{self.input.receive_guest_spent(input,progress,work_units_spent,ActorGuestPhase::Dispatched)}
 pub(super) fn take_received_more_work(&mut self,receipt:RetainedTurnReceipt)->Option<TurnResult>{if !self.pending.as_ref().is_some_and(|result|matches!(result.status,semio_framework::kernel::TurnStatus::MoreWork)){return None}let mut result=self.pending.take()?;result.retained_receipt=receipt;Some(result)}
 pub(super) fn receive_failed_call(&mut self,call:semio_framework_plugin_guest_contract::original_actor_context::OriginalActorFixedCall)->Result<RetainedTurnReceipt,ValueError>{assert!(self.failed.is_none(),"original Event has one returned failure");self.failed=Some(call);self.input.receive_guest_spent(call.input,call.spent,call.work_units_spent,ActorGuestPhase::Dispatched)?;self.input.return_actor_turn()}
 pub(super) fn retain_trap(&mut self,trap:TurnFault){assert!(self.trap.is_none(),"original Event has one unreturned trap");*self.trap=Some(trap);}
 pub(super) fn retain_receiving_refusal(&mut self,error:ValueError){assert!(self.receiving_refusal.is_none(),"original Event has one held receiving refusal");*self.receiving_refusal=Some(error);}
 pub(super) fn retain_source_refusal(&mut self,error:ValueError){assert!(self.source_refusal.is_none(),"original Event has one held source close refusal");*self.source_refusal=Some(error);}
 pub(super) fn retain_fixed_call(&mut self,call:semio_framework_plugin_guest_contract::original_actor_context::OriginalActorFixedCall){if self.failed.is_none(){self.failed=Some(call);}}
 pub(super) fn pending_raw_return(&self)->Option<semio_framework_actor::OriginalActorGuestReturn>{self.pending.as_ref().map(|result|{let receipt=result.retained_receipt;semio_framework_actor::OriginalActorGuestReturn{input:receipt.input,spent:receipt.spent,work_units_spent:receipt.work_units_spent,claimed_remaining:Some(receipt.remaining),claimed_remaining_fuel:Some(receipt.remaining_fuel)}})}
 pub(super) fn terminal_is_empty(&self)->bool{self.mesh.is_none()&&self.input.original().is_none()&&self.retirement.is_none()&&self.pending.is_none()&&self.trap.is_none()&&self.failed.is_none()&&self.receiving_refusal.is_none()&&self.source_refusal.is_none()}
 pub(super) fn source_close_step(&mut self,grant:RetainedCloneGrant,work:&mut u64)->Result<RetainedCloneProgress,ValueError>{
  if self.pending.is_none(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original Event has no terminal guest result"))}
  if let Some(cursor)=self.retirement.as_mut(){if cursor.terminal_is_empty(){return Ok(Default::default())}let demand=cursor.next_demand(grant.maximum_copy_bytes)?;if grant.maximum_items==0||grant.maximum_copy_bytes<demand.copy_bytes||grant.maximum_capacity_bytes<demand.capacity_bytes||grant.maximum_release_bytes<demand.release_bytes||grant.maximum_depth<demand.depth{return Ok(Default::default())}*work=1;return cursor.close_step(grant).map(|step|step.progress())}
  if self.input.original().is_some(){let bytes=semio_framework_value::retirement::owned_retirement_birth_bytes::<Event>();if grant.maximum_items==0||grant.maximum_depth==0||grant.maximum_capacity_bytes<bytes{return Ok(Default::default())}*work=1;let event=self.input.take_dispatched_input()?.expect("quoted original Event source");return match semio_framework_value::retirement::admit_owned_retirement(event,grant){Ok((cursor,progress))=>{self.frame_bytes=progress.retained_capacity_bytes;*self.retirement=Some(cursor);Ok(progress)},Err((error,event))=>{self.input.restore_dispatched_input(event).unwrap_or_else(|_|panic!("refused original Event retirement returns its exact source"));Err(error)}}}
  Ok(Default::default())
 }
 pub(super) fn release_empty_cursor(&mut self,grant:RetainedCloneGrant,work:&mut u64)->Option<RetainedCloneProgress>{let cursor=self.retirement.as_ref()?;if !cursor.terminal_is_empty()||grant.maximum_items==0||grant.maximum_depth==0||grant.maximum_release_bytes<self.frame_bytes{return None}*work=1;let bytes=self.frame_bytes;drop(self.retirement.take());self.frame_bytes=0;Some(RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()})}
 pub(super) fn take_closed_result(&mut self,receipt:RetainedTurnReceipt)->Option<TurnResult>{if self.input.original().is_some()||self.retirement.is_some(){return None}let mut result=self.pending.take()?;result.retained_receipt=receipt;Some(result)}
}
impl Drop for OriginalShardEvent{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original Event reached Drop before source and pending result returned")}}

impl OriginalShardEvent{
 pub(super) fn has_mesh_receiving(&self)->bool{self.mesh.is_some()||self.pending.as_ref().is_some_and(|result|result.effects.iter().any(|effect|matches!(effect,Effect::SendMessage{target:semio_framework::kernel::MessageEndpoint::Shell{..},payload}if UiNativeMeshMessage::is_mesh_message(payload))))}
 pub(super) fn mesh_awaits_host(&self)->bool{self.mesh.as_ref().is_some_and(|mesh|mesh.sent&&!mesh.accepted)}
 pub(super) fn mesh_is_accepted(&self)->bool{self.mesh.as_ref().is_some_and(|mesh|mesh.accepted)}
 pub(super) fn prepare_mesh_packet_step(&mut self,actor:u64,policy:RetainedCloneGrant,work_fuel:u64,deadline_us:u64,observed_now:Option<u64>)->Result<Option<super::ShardOutcome>,ValueError>{
  let issued=*self.input.issued_input().ok_or_else(||mesh_refusal("original mesh has no held issued input"))?;if deadline_us==0||deadline_us>issued.work.absolute_deadline_us{return Err(mesh_refusal("original mesh semantic deadline exceeds its immutable source"))}if observed_now.is_none_or(|now|now>=deadline_us){return Ok(None)}
  if self.mesh.is_none(){if self.input.work_units_spent()>=work_fuel{return Ok(None)}if issued.return_original(self.input.spent(),self.input.work_units_spent())?.remaining_fuel==0{return Ok(None)}let Some((index,payload))=self.pending.as_ref().and_then(|result|result.effects.iter().enumerate().find_map(|(index,effect)|match effect{Effect::SendMessage{target:semio_framework::kernel::MessageEndpoint::Shell{..},payload}if UiNativeMeshMessage::is_mesh_message(payload)=>Some((index,payload)),_=>None}))else{return Ok(None)};if payload.len()!=UI_NATIVE_MESH_MESSAGE_BYTES{return Err(mesh_refusal("original mesh source fixed extent is malformed"))}let source=(payload.as_ptr()as usize,payload.len(),payload.capacity());let Some(input)=self.checkout_result_receiving(policy)?else{return Ok(None)};let policy=self.input.guest_policy(input)?;self.mesh=Some(OriginalShardMeshSending{input,policy,index,sequence:self.mesh_sequence,source,bytes:[0;UI_NATIVE_MESH_MESSAGE_BYTES],offset:0,spent:RetainedCloneProgress{copied_items:1,..Default::default()},work:1,fuel:work_fuel-self.input.work_units_spent(),sent:false,accepted:false,close:ManuallyDrop::new(None)});return Ok(None)}
  let mesh=self.mesh.as_mut().unwrap();if mesh.sent{return Ok(None)}let remaining=mesh_remaining(mesh.policy,mesh.spent)?;if remaining.maximum_items==0||remaining.maximum_depth==0||mesh.work>=mesh.fuel{return Ok(None)}let payload=match self.pending.as_ref().and_then(|result|result.effects.get(mesh.index)){Some(Effect::SendMessage{payload,..})=>payload,_=>return Err(mesh_refusal("original mesh Effect source changed before return"))};if (payload.as_ptr()as usize,payload.len(),payload.capacity())!=mesh.source{return Err(mesh_refusal("original mesh payload source was replaced"))}
  if mesh.offset<UI_NATIVE_MESH_MESSAGE_BYTES{let length=(UI_NATIVE_MESH_MESSAGE_BYTES-mesh.offset).min(64);if remaining.maximum_copy_bytes<length{return Ok(None)}mesh.bytes[mesh.offset..mesh.offset+length].copy_from_slice(&payload[mesh.offset..mesh.offset+length]);mesh.offset+=length;mesh.work+=1;mesh.spent=mesh.spent.checked_add(RetainedCloneProgress{copied_items:1,copied_bytes:length,..Default::default()})?;return Ok(None)}
  if remaining.maximum_copy_bytes<UI_NATIVE_MESH_MESSAGE_BYTES{return Ok(None)}mesh.work+=1;mesh.spent=mesh.spent.checked_add(RetainedCloneProgress{copied_items:1,copied_bytes:UI_NATIVE_MESH_MESSAGE_BYTES,..Default::default()})?;mesh.sent=true;Ok(Some(super::ShardOutcome::OriginalMesh{actor,input:mesh.input,retained_policy:mesh_remaining(mesh.policy,mesh.spent)?,work_fuel:mesh.fuel-mesh.work,deadline_us,receiving_sequence:mesh.sequence,source_spent:mesh.spent,source_work_units_spent:mesh.work,bytes:mesh.bytes}))
 }
 pub(super) fn receive_mesh_progress(&mut self,input:RetainedTurnInput,sequence:u64,spent:RetainedCloneProgress,work:u64,accepted:bool)->Result<(),ValueError>{let mesh=self.mesh.as_mut().ok_or_else(||mesh_refusal("original mesh receiving has no stationary source"))?;if !mesh.sent||mesh.accepted||mesh.input!=input||mesh.sequence!=sequence{return Err(mesh_refusal("original mesh receive delta differs from its exclusive checkout and sequence"))}let total=mesh.spent.checked_add(spent)?;let work=mesh.work.checked_add(work).ok_or_else(||mesh_refusal("original mesh receive actual work overflow"))?;self.input.receive_guest_spent(input,total,work,ActorGuestPhase::Dispatched)?;if work>mesh.fuel{return Err(mesh_refusal("original mesh receive actual work exceeds its held business loan"))}if !accepted{return Err(mesh_refusal("original mesh destination refused its whole pending source"))}mesh.accepted=true;Ok(())}
 pub(super) fn close_mesh_effect_step(&mut self,policy:RetainedCloneGrant)->Result<bool,ValueError>{if !self.mesh_is_accepted(){return Err(mesh_refusal("original mesh source cannot retire before funded receiving handoff"))}let Some(input)=self.input.checkout_guest(policy)?else{return Ok(false)};let grant=self.input.guest_policy(input)?;let mut work=0;let result=(||{if input.work.fuel==0{return Ok((false,Default::default()))}let mesh=self.mesh.as_mut().unwrap();if let Some(close)=mesh.close.as_mut(){if !close.terminal_is_empty(){let demand=close.selected_demand(grant.maximum_copy_bytes)?;if !mesh_fits(grant,demand){return Ok((false,Default::default()))}work=1;let step=close.step(RetainedCloneGrant{maximum_items:1,..grant})?;return Ok((false,step.progress()))}if grant.maximum_items==0||grant.maximum_depth==0{return Ok((false,Default::default()))}work=1;mesh.close.take();self.mesh=None;self.mesh_sequence=self.mesh_sequence.checked_add(1).ok_or_else(||mesh_refusal("original mesh transport sequence exhausted"))?;return Ok((true,RetainedCloneProgress{copied_items:1,..Default::default()}))}let result=self.pending.as_mut().unwrap();let copied=(result.effects.len()-mesh.index-1).checked_mul(size_of::<Effect>()).ok_or_else(||mesh_refusal("original mesh Effect relocation extent overflow"))?;if grant.maximum_items==0||grant.maximum_depth==0||grant.maximum_copy_bytes<copied.checked_mul(2).ok_or_else(||mesh_refusal("original mesh refused relocation extent overflow"))?{return Ok((false,Default::default()))}work=1;let effect=result.effects.remove(mesh.index);let progress=RetainedCloneProgress{copied_items:1,copied_bytes:copied,..Default::default()};match ControlledRetirement::new(effect){Ok(close)=>{*mesh.close=Some(close);Ok((false,progress))},Err((error,effect))=>{result.effects.insert(mesh.index,effect);Err(error.with_retained_progress(RetainedCloneProgress{copied_bytes:copied*2,..progress}))}}})();let progress=match &result{Ok((_,progress))=>*progress,Err(error)=>error.retained_progress()};self.input.receive_guest_spent(input,progress,work,ActorGuestPhase::Dispatched)?;result.map(|(complete,_)|complete)}
}
fn mesh_refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
fn mesh_remaining(grant:RetainedCloneGrant,spent:RetainedCloneProgress)->Result<RetainedCloneGrant,ValueError>{if !spent.fits(grant){return Err(mesh_refusal("original mesh source exceeds its held loan"))}Ok(RetainedCloneGrant{maximum_items:grant.maximum_items-spent.copied_items,maximum_copy_bytes:grant.maximum_copy_bytes-spent.copied_bytes,maximum_capacity_bytes:grant.maximum_capacity_bytes-spent.retained_capacity_bytes,maximum_release_bytes:grant.maximum_release_bytes-spent.released_bytes,maximum_depth:grant.maximum_depth})}
fn mesh_fits(grant:RetainedCloneGrant,demand:semio_framework_value::RetirementDemand)->bool{grant.maximum_items!=0&&grant.maximum_copy_bytes>=demand.copy_bytes&&grant.maximum_capacity_bytes>=demand.capacity_bytes&&grant.maximum_release_bytes>=demand.release_bytes&&grant.maximum_depth>=demand.depth}
